  const {
    layout,
    toolbar,
    results
  } = useInbox({});
  const {
    isAnswered,
    acceptAll,
    rejectAll,
    consent
  } = useConsent();
  const [language, setLanguage] = useState<'nb' | 'en' | 'nn'>('nb');
